const event = $input.first()?.json ?? {};
const execution = event.execution ?? {};
const error = execution.error ?? event.error ?? {};

const sanitize = (value, maxLength = 900) => {
  let text = String(value ?? '');
  text = text
    .replace(/(authorization\s*[:=]\s*)(?:bearer\s+)?[^\s,;]+/gi, '$1[REDACTED]')
    .replace(/\bbot\d{6,}:[A-Za-z0-9_-]{20,}\b/g, 'bot[REDACTED]')
    .replace(/((?:api[_-]?key|token|password|secret|credential)\s*[:=]\s*)["']?[^"'\s,;]+/gi, '$1[REDACTED]')
    .replace(/postgres(?:ql)?:\/\/[^@\s]+@/gi, 'postgresql://[REDACTED]@')
    .replace(/[\u0000-\u001F\u007F]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return text.slice(0, maxLength);
};

const workflowName = sanitize(event.workflow?.name ?? 'Unknown workflow', 180);
const failedNode = sanitize(
  execution.lastNodeExecuted ?? event.lastNodeExecuted ?? 'Unknown node',
  180,
);
const summary = sanitize(
  error.description ??
    error.cause?.message ??
    error.message ??
    'Unknown workflow error',
  900,
);
const genericMessage = sanitize(error.message, 600);
const technicalDetail =
  genericMessage &&
  genericMessage.toLocaleLowerCase('en-US') !== summary.toLocaleLowerCase('en-US')
    ? genericMessage
    : '';

const errorType = sanitize(error.name ?? error.type, 100);
const httpCode = sanitize(
  error.httpCode ??
    error.statusCode ??
    error.response?.statusCode ??
    error.context?.httpCode,
  20,
);
const executionUrl = sanitize(execution.url ?? 'Not available', 700);
const occurredAt = new Date().toISOString();

const lines = [
  '⚠️ n8n workflow failed',
  '',
  `Workflow: ${workflowName}`,
  `Node: ${failedNode}`,
  `Error: ${summary}`,
];

if (technicalDetail) lines.push(`Detail: ${technicalDetail}`);
if (errorType) lines.push(`Type: ${errorType}`);
if (httpCode) lines.push(`HTTP: ${httpCode}`);

lines.push(`Time: ${occurredAt}`);
lines.push(`Execution: ${executionUrl}`);

return [{ json: { message: lines.join('\n').slice(0, 3500) } }];
